A class answers names it does not hold from a hook, and the hook is watched as three reads are made. The program below is run under CPython 3.14.3. Which statement about the two hooks is correct?

class G:
    def __getattr__(self, name):
        print("hook", name)
        return name.upper()

g = G()
print(g.missing)
print(getattr(g, "other", "fallback"))
print("missing" in g.__dict__)

A class answers any name that starts with a letter and refuses the rest, and both kinds of read are made. The program below is run under CPython 3.14.3. What does it print?

class G:
    def __getattr__(self, name):
        print("hook", name)
        if name.startswith("x"):
            return name.upper()
        raise AttributeError(name)

g = G()
print(g.xa)
try:
    print(g.zz)
except AttributeError as e:
    print("AttributeError:", e)
print(getattr(g, "q", "fallback"))

Two class attributes both define a read hook, one of them also defines a write hook, and each is put on a class that then has a value written on an object. The program below is run under CPython 3.14.3. Which statement about the two is correct?

class OnlyGet:
    def __get__(self, obj, objtype=None):
        return "computed"

class GetSet:
    def __get__(self, obj, objtype=None):
        return "read"
    def __set__(self, obj, value):
        raise AttributeError("read only")

class A:
    n = OnlyGet()

class B:
    d = GetSet()

a, b = A(), B()
a.n = "mine"
print(a.n, A.n)
try:
    b.d = "mine"
except AttributeError as e:
    print("AttributeError:", e)
print(hasattr(OnlyGet, "__set__"), hasattr(GetSet, "__set__"))

A class attribute answers a read with a fixed word, an object of that class stores its own value under the same name, and the two are then read. The program below is run under CPython 3.14.3. What does it print?

class Nondata:
    def __get__(self, obj, objtype=None):
        return "computed"

class D:
    v = Nondata()

d = D()
print(d.v)
d.v = "mine"
print(d.v, D.v, "v" in d.__dict__)

A class defines a value that answers a read and refuses a write, and a program tries to store one. The program below is run under CPython 3.14.3. What happens, and what does the object hold afterwards?

class Data:
    def __get__(self, obj, objtype=None):
        return "got"
    def __set__(self, obj, value):
        raise AttributeError("read only")

class E:
    f = Data()

e = E()
try:
    e.f = "x"
except AttributeError as err:
    print("AttributeError:", err)
print(e.f, len(e.__dict__))

A class attribute is told the name it was given and the class it was given it in, and two of them are put in one class body. The program below is run under CPython 3.14.3. What does it print?

class Log:
    def __set_name__(self, owner, name):
        self.owner, self.name = owner.__name__, name
    def __get__(self, obj, objtype=None):
        return f"{self.owner}.{self.name}"

class C:
    a = Log()
    b = Log()

print(C().a, C().b)
print(C.__dict__["a"].owner, C.__dict__["b"].name)

An attribute records the two things it is told at class creation and then reports them. The program below is run under CPython 3.14.3. Which statement about what it is told is correct?

class Note:
    def __set_name__(self, owner, name):
        self.seen = (owner.__name__, name)
    def __get__(self, obj, objtype=None):
        return self.seen

class Doc:
    title = Note()
    body = Note()

d = Doc()
print(d.title)
print(d.body)
print(len(Doc.__dict__["title"].seen))

A class exposes one name whose read doubles what it stores and whose write adds one before storing, and both directions are exercised. The program below is run under CPython 3.14.3. What does it print?

class P2:
    def __init__(self):
        self._x = 1

    @property
    def x(self):
        return self._x * 2

    @x.setter
    def x(self, v):
        self._x = v + 1

p = P2()
print(p.x, p._x)
p.x = 5
print(p.x, p._x)

One class exposes a name that recomputes on every read and another that is computed once and then reused, and a counter records how many times the body ran. The program below is run under CPython 3.14.3. Which pair names what this program prints and why?

import functools

class M:
    def __init__(self):
        self.calls = 0

    @property
    def live(self):
        self.calls += 1
        return self.calls

    @functools.cached_property
    def once(self):
        self.calls += 1
        return self.calls

m = M()
print(m.live, m.live, m.calls)
print(m.once, m.once, m.calls)

A metaclass defines two hooks and both are watched as a class is declared. The program below is run under CPython 3.14.3. Which statement about the two hooks is correct?

class Meta(type):
    def __new__(mcls, name, bases, ns):
        print("new", name)
        return super().__new__(mcls, name, bases, ns)
    def __init__(cls, name, bases, ns):
        print("init", name)
        super().__init__(name, bases, ns)

class P(metaclass=Meta):
    pass

print(P.__name__, type(P).__name__)

A metaclass reports the name and the arguments of every construction, and a class using it is built once. The program below is run under CPython 3.14.3. What does it print?

class Meta(type):
    def __call__(cls, *a, **k):
        print("Meta.__call__", cls.__name__, a)
        return super().__call__(*a, **k)

class WithMeta(metaclass=Meta):
    def __init__(self, v):
        self.v = v

print(WithMeta(3).v)
print(type(WithMeta).__name__)

A metaclass is asked for the namespace before the class body runs, and what the body leaves behind is inspected. The program below is run under CPython 3.14.3. What does it print?

class PMeta(type):
    @staticmethod
    def __prepare__(name, bases, **kw):
        print("prepare", name)
        return {}

class Q(metaclass=PMeta):
    x = 1

print(Q.x, type(Q.__dict__).__name__)
print("x" in Q.__dict__)

A base class records a keyword given in a subclass statement, and one subclass is declared. The program below is run under CPython 3.14.3. What does it print?

class Base2:
    def __init_subclass__(cls, /, tag=None, **kw):
        cls.tag = tag
        super().__init_subclass__(**kw)

class Child(Base2, tag="v2"):
    pass

print(Child.tag, Base2.__name__)
print("tag" in Child.__dict__)

A subclass statement carries a keyword that the base class hook does not claim and does not pass on, and the program does not finish normally. The program below is run under CPython 3.14.3. What reaches the screen?

class Base2:
    def __init_subclass__(cls, /, tag=None, **kw):
        cls.tag = tag
        super().__init_subclass__(**kw)

try:
    class Bad(Base2, nope=1):
        pass
except TypeError as e:
    print("TypeError:", e)

A class names two parents that share one grandparent, and the order the interpreter walks is printed. The program below is run under CPython 3.14.3. What does it print?

class A:
    pass

class B(A):
    pass

class C(A):
    pass

class D(B, C):
    pass

print([k.__name__ for k in D.__mro__])
print(issubclass(D, C), C in D.__mro__, D.__mro__[1] is B)

Two parents override the same inherited method, a class inherits from both without overriding it, and the order plus the method it finds are printed. The program below is run under CPython 3.14.3. Which statement about that order is correct?

class A:
    def who(self):
        return "A"

class B(A):
    def who(self):
        return "B"

class C(A):
    def who(self):
        return "C"

class D(B, C):
    pass

d = D()
print(d.who())
print(len(D.__mro__))
print([k.__name__ for k in D.__mro__][:3])
print(D.who is B.who and D.who is C.who)

A class defines both an addition hook and a reflected one, and the same two values are added in both orders. The program below is run under CPython 3.14.3. What does it print?

class V:
    def __init__(self, v):
        self.v = v

    def __add__(self, o):
        return f"add{getattr(o, 'v', o)}"

    def __radd__(self, o):
        return f"radd{getattr(o, 'v', o)}"

v = V(2)
print(v + 3, 3 + v)
print(hasattr(V, "__add__"), hasattr(V, "__radd__"))

A class defines both multiplication hooks, and the same value is multiplied on the left and on the right. The program below is run under CPython 3.14.3. What does it print?

class V:
    def __mul__(self, k):
        return f"mul{k}"

    def __rmul__(self, k):
        return f"rmul{k}"

v = V()
print(2 * v, v * 2)
print(hasattr(V, "__mul__"), hasattr(V, "__rmul__"))

Two classes offer a whole number, one through the hook the machinery asks for and one through a different hook, and each is used as a position. The program below is run under CPython 3.14.3. Which statement about the two is correct?

class Good:
    def __index__(self):
        return 2

class Bad:
    def __int__(self):
        return 2

print([10, 11, 12][Good()])
try:
    print([10, 11, 12][Bad()])
except TypeError as e:
    print("TypeError:", e)
print("abc"[Good()], "abc"[:Good()])

Three classes report a length of zero, two of them also report a truth value, and the results are printed. The program below is run under CPython 3.14.3. What does it print?

class L:
    def __len__(self):
        return 0

    def __bool__(self):
        return True

class M2:
    def __len__(self):
        return 0

print(bool(L()), bool(M2()))
print(len(L()), len(M2()))
print(bool([L(), M2()]))

A class answers an addition by declining it, and the same addition is then tried inside a handler. The program below is run under CPython 3.14.3. What does it print?

class R:
    def __add__(self, o):
        return NotImplemented

try:
    R() + 1
except TypeError as e:
    print("TypeError:", e)

print(R.__add__(R(), 1) is NotImplemented)
print(hasattr(R, "__radd__"))

Two classes each decline an operation in one position, and both positions of the same expression are tried. The program below is run under CPython 3.14.3. Which statement about the two hooks is correct?

class P:
    def __add__(self, o):
        return NotImplemented

    def __radd__(self, o):
        return "radd"

class Q:
    def __add__(self, o):
        return "qadd"

    def __radd__(self, o):
        return NotImplemented

p, q = P(), Q()
print(p.__add__(1) is NotImplemented, p.__radd__(1))
print(q.__add__(1), q.__radd__(1) is NotImplemented)
print(hasattr(P, "__radd__"), hasattr(Q, "__add__"))

A class with no table of slots, one whose table names the slot the reference machinery needs, and one whose table is written out in full are all tried, and a built-in object is tried afterwards. The program below is run under CPython 3.14.3. Which statement about the ability to be referenced is correct?

import weakref

def can(obj):
    try:
        return weakref.ref(obj) is not None
    except TypeError:
        return False

class Plain:
    def __init__(self):
        self.peer = None

class Slotted:
    __slots__ = ("peer", "__weakref__")

class Empty:
    __slots__ = ()

print(can(Plain()), can(Slotted()), can(Empty()))
try:
    weakref.ref(object())
except TypeError as e:
    print("TypeError:", e)

One function calls another, the inner call hands back its own frame, and the chain of frames is walked from there. The program below is run under CPython 3.14.3. What does it print?

import inspect

def inner(n):
    doubled = n * 2
    return doubled, inspect.currentframe()

def outer(n):
    return inner(n)

doubled, f = outer(3)
print(f.f_code.co_name, f.f_back.f_code.co_name)
print(f.f_back.f_back.f_code.co_name)
print(sorted(f.f_locals), sorted(f.f_back.f_locals))
print(f.f_code.co_varnames, f.f_back.f_code.co_varnames)

A call takes a table of its names, writes into that table, and hands the table back, and a second call asks twice whether the two tables are the same object. The program below is run under CPython 3.14.3. Which statement about the table is correct?

def f(n):
    local = n * 2
    snap = locals()
    snap["local"] = 99
    return local, snap["local"], len(snap)

def g():
    return locals() is locals()

print(f(3))
print(f.__code__.co_varnames)
print(g())
print(locals() is f.__globals__)

A metaclass answers the instance test itself, and the same test is asked of a tuple, a list, the subclass test and the class object. The program below is run under CPython 3.14.3. What does it print?

class Meta(type):
    def __instancecheck__(cls, obj):
        return isinstance(obj, tuple)

class Fake(metaclass=Meta):
    pass

print(isinstance((1, 2), Fake), isinstance([1, 2], Fake))
print(issubclass(tuple, Fake))
print(type(Fake).__name__)
print(isinstance(Fake, type))
